import math

from rope import REST_LENGTH, simulate


def test_segments_within_one_percent():
    rope = simulate(300)
    tol = REST_LENGTH * 0.01
    for i in range(len(rope.particles) - 1):
        a, b = rope.particles[i], rope.particles[i + 1]
        seg = math.hypot(b.x - a.x, b.y - a.y)
        assert abs(seg - REST_LENGTH) <= tol, (
            f"segment {i} length {seg} deviates more than 1% from {REST_LENGTH}"
        )


def test_total_length_within_two_percent_of_95():
    rope = simulate(300)
    total = sum(
        math.hypot(
            rope.particles[i + 1].x - rope.particles[i].x,
            rope.particles[i + 1].y - rope.particles[i].y,
        )
        for i in range(len(rope.particles) - 1)
    )
    expected = 95.0
    assert abs(total - expected) <= expected * 0.02, (
        f"total length {total} deviates more than 2% from {expected}"
    )


def test_pinned_particle_never_moved():
    # Verify across every tick, from the very first one.
    rope = Rope() if False else None  # placeholder to keep import minimal
    from rope import Rope

    r = Rope()
    assert (r.particles[0].x, r.particles[0].y) == (r.pin_x, r.pin_y)
    for _ in range(300):
        r.tick()
        assert (r.particles[0].x, r.particles[0].y) == (r.pin_x, r.pin_y)


def test_bottom_particle_hangs_below_pin():
    rope = simulate(300)
    bottom = rope.particles[-1]
    assert abs(bottom.x - rope.pin_x) < 1e-3, (
        f"bottom particle x={bottom.x}, pin x={rope.pin_x}"
    )

